import{_ as o,o as t,c as a,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const c="/shots/08-onboarding.png",r="/shots/05-new-project.png",b=JSON.parse('{"title":"첫 프로젝트 만들기","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/first-ticket"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/first-ticket"}],["meta",{"property":"og:title","content":"첫 프로젝트 만들기"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/first-ticket.md","filePath":"docs/first-ticket.md"}'),s={name:"docs/first-ticket.md"};function n(p,e,i,l,h,m){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="첫-프로젝트-만들기" tabindex="-1">첫 프로젝트 만들기 <a class="header-anchor" href="#첫-프로젝트-만들기" aria-label="Permalink to &quot;첫 프로젝트 만들기&quot;">​</a></h1><p>dira는 프로젝트 단위로 프로토콜, 티켓, 페르소나 등을 다룹니다. 서로 다른 프로젝트 간에는 영향을 받지 않습니다.</p><h2 id="처음-열면-보이는-화면" tabindex="-1">처음 열면 보이는 화면 <a class="header-anchor" href="#처음-열면-보이는-화면" aria-label="Permalink to &quot;처음 열면 보이는 화면&quot;">​</a></h2><p>프로젝트가 0건일 때의 홈입니다. 위쪽 띠에 <code>프로젝트</code>가 있고, 본문은 <code>dira</code>와 한 줄로 시작합니다. 그 한 줄이 <code>등록된 프로젝트가 없습니다. 하나 만들면 시작합니다.</code>입니다. 아래로 <code>이미 만들어 둔 .dira가 있다면 등록합니다.</code>와 <code>프로젝트 등록</code> 버튼이 한 줄로 지나가고, 그다음이 <code>새 프로젝트</code> 카드입니다. 폼이 이미 열려 있습니다.</p><p><img src="'+c+'" alt="프로젝트가 0건일 때의 첫 화면. 등록된 프로젝트가 없다는 한 줄 아래에 새 프로젝트 카드가 펼쳐져 있고, 이름·프로젝트 폴더·통합 브랜치·스펙 문서 칸과 프로젝트 만들기 버튼이 있습니다. 그 위 한 줄에 이미 만들어 둔 .dira를 등록하는 버튼이 따로 있습니다."></p><p>이 장에서 채우는 것이 그 폼입니다. 헤더 오른쪽에는 <code>설정</code>뿐입니다. 폼이 눈앞에 펼쳐져 있는데 그 폼을 여는 버튼을 같은 화면에 또 세울 이유가 없기 때문입니다. 위의 등록 한 줄은 우회로입니다. <code>.dira</code>를 이미 만들어 뒀거나 남이 쓰던 프로젝트를 받아온 분이 그리로 갑니다. 처음이라면 지나쳐도 됩니다.</p><h2 id="폼에-넣는-것" tabindex="-1">폼에 넣는 것 <a class="header-anchor" href="#폼에-넣는-것" aria-label="Permalink to &quot;폼에 넣는 것&quot;">​</a></h2><p>카드 제목 밑에 한 줄이 붙어 있습니다. 이 폼이 하는 일이 그 문장에 다 들어 있습니다.</p><blockquote><p><code>.dira를 만들고 워커 하나를 crontab에 올립니다 — 30초 뒤부터 티켓을 물어갑니다.</code></p></blockquote><p>crontab은 cron이 읽는 예약 목록입니다. 여기에 한 줄이 올라가면 그때부터 맥이 알아서 워커를 30초마다 부릅니다.</p><table tabindex="0"><thead><tr><th>필드</th><th>넣는 것</th></tr></thead><tbody><tr><td><code>이름</code></td><td>화면에 보일 이름입니다. 아래에 주소에 쓰일 이름(슬러그)이 미리보기로 뜹니다</td></tr><tr><td><code>프로젝트 폴더</code></td><td><strong><code>.dira</code>의 부모</strong>입니다. <code>~/Projects/myproject</code>처럼 적으면 그 밑에 <code>.dira</code>를 만듭니다. 칸 아래 도움말도 같은 말을 합니다(<code>여기에 .dira를 만듭니다. ~는 확장됩니다</code>). 폴더가 없으면 만듭니다</td></tr><tr><td><code>통합 브랜치</code></td><td>세션이 결과를 올릴 브랜치입니다. 기본값은 <code>main</code>입니다</td></tr><tr><td><code>스펙 문서</code></td><td>선택입니다. 프로젝트 스펙 파일 경로(<code>docs/DESIGN.md</code> 같은 것)를 적습니다. 아직 없는 파일을 미리 적어도 됩니다</td></tr></tbody></table><p>도움말에 나오는 <code>~</code>는 홈 폴더를 가리키는 줄임말입니다. <code>~/Projects/myproject</code>라고 적으면 <code>/Users/&lt;사용자 이름&gt;/Projects/myproject</code>와 같은 자리를 뜻합니다.</p><p><code>프로젝트 만들기</code>를 누르세요.</p><p>이미 프로젝트가 있는 화면에서는 같은 폼이 다이얼로그로 열립니다. 목록 위 <code>새로 만들기</code>가 그 트리거고, 칸도 도움말도 제출 버튼도 방금 채운 것과 같습니다.</p><p><img src="'+r+`" alt="새 프로젝트 만들기 다이얼로그. 이름·프로젝트 폴더·통합 브랜치·스펙 문서 칸과 프로젝트 만들기 버튼."></p><h2 id="프로젝트가-만들어졌습니다" tabindex="-1">프로젝트가 만들어졌습니다 <a class="header-anchor" href="#프로젝트가-만들어졌습니다" aria-label="Permalink to &quot;프로젝트가 만들어졌습니다&quot;">​</a></h2><p>고른 폴더 밑에 <code>.dira</code>가 이렇게 놓입니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;프로젝트&gt;/.dira/</span></span>
<span class="line"><span>  tickets/                                    빈 큐</span></span>
<span class="line"><span>  protocols/AGENTS.md                         협업 프로토콜 — 브랜치·스펙 문서가 치환된 상태</span></span>
<span class="line"><span>  protocols/tickets.md                        티켓 쪼개는 기준 — 문법은 dira의 코어가 들고 있다</span></span>
<span class="line"><span>  personas/{pm,developer,qa,designer}/PROFILE.md</span></span>
<span class="line"><span>  workers/w1.sh                               워커 하나. 실행 권한까지 붙어 있다</span></span></code></pre></div><p>여기에 <strong>crontab 등록</strong>(<code>w1.sh</code>를 30초마다 부르는 줄)과 <strong>레지스트리 등록</strong>(앱이 이 프로젝트를 목록에 들고 있게 하는 것)이 더해집니다. <code>&lt;프로젝트&gt;</code> 안에 만드는 것은 <code>.dira</code> 하나뿐이고 프로젝트 소스에는 손대지 않습니다.</p><p>워커는 하나입니다. 한 번에 티켓 하나가 돈다는 뜻입니다. 동시에 두 건 이상 돌리고 싶으면 워커를 더 만들면 됩니다. <a href="/docs/worker">워커</a>에서 다룹니다.</p><h2 id="이제-요구할-차례입니다" tabindex="-1">이제 요구할 차례입니다 <a class="header-anchor" href="#이제-요구할-차례입니다" aria-label="Permalink to &quot;이제 요구할 차례입니다&quot;">​</a></h2><p>성공하면 목록에 행이 하나 생기고, 폼이 있던 자리가 결과 카드로 바뀝니다. 카드 안은 세 줄입니다. 만든 파일 수, 유도한 엔진 레포 경로, 그리고 마지막 줄입니다.</p><blockquote><p><code>crontab에 등록됨 — 30초 뒤부터 티켓을 물어갑니다</code></p></blockquote><p>이 줄이 보이면 끝난 것입니다. 카드에는 <code>보드 열기</code>와 <code>닫기</code>가 같이 있고, <code>닫기</code>를 눌러야 결과가 접힙니다. 급하지 않으면 읽고 나서 닫으세요. 잘못 적은 경로를 알아챌 자리가 여기입니다.</p><h2 id="승인-창-·-등록-실패-·-이미-있는-dira" tabindex="-1">승인 창 · 등록 실패 · 이미 있는 <code>.dira</code> <a class="header-anchor" href="#승인-창-·-등록-실패-·-이미-있는-dira" aria-label="Permalink to &quot;승인 창 · 등록 실패 · 이미 있는 \`.dira\`&quot;">​</a></h2><p>macOS가 승인 창을 띄웁니다. crontab에 쓰려면 <code>앱 관리</code> 권한이 필요합니다. 만드는 동안 폼 아래에 <code>권한 창이 뜨면 [허용]을 누르세요 — crontab 등록이 그 대답을 기다립니다.</code>가 떠 있습니다. <code>허용</code>을 누르면 하던 등록이 그대로 이어집니다. 창을 방치하면 3분 뒤 등록만 실패로 떨어집니다.</p><p>crontab 등록만 실패해도 프로젝트는 만들어진 것입니다. 만든 파일을 되돌리지 않고, 사유와 함께 화면이 등록 명령을 띄웁니다. 복사해서 터미널에 붙여 넣으면 그 자리에서 끝납니다. 실패했을 때만 나오는 우회로입니다.</p><p>고른 폴더에 이미 <code>.dira</code>가 있으면 만들지 않습니다. 안에 <code>tickets/</code>나 <code>workers/</code>가 있으면 <code>&lt;경로&gt;/.dira는 이미 dira 프로젝트입니다. 만들지 않고 등록하세요.</code>와 등록 다이얼로그를 여는 버튼이 뜹니다. 있는 파일을 덮는 경로는 이 앱에 없습니다.</p><h2 id="아직-비어-있는-큐" tabindex="-1">아직 비어 있는 큐 <a class="header-anchor" href="#아직-비어-있는-큐" aria-label="Permalink to &quot;아직 비어 있는 큐&quot;">​</a></h2><p>프로젝트가 돌기 시작했지만 물어갈 티켓이 없습니다. 다음 장에서 하고 싶은 말을 한 칸에 넣으면 pm이 그것을 티켓으로 쪼갭니다.</p><p>다음은 <a href="/docs/requirements">요구사항 접수하기</a>입니다.</p>`,31)])])}const u=o(s,[["render",n]]);export{b as __pageData,u as default};
